class CircularDependencyError(Exception):
    """Raised when a circular dependency is detected during resolution."""
    pass


class DependencyResolver:
    @staticmethod
    def resolve(dependencies: dict[str, list[str]]) -> list[list[str]]:
        """
        Resolves task dependencies into execution stages/batches.

        :param dependencies: Mapping of task_name -> list of task_names it depends on.
        :return: A list of stages, where each stage is a sorted list of task names
                 that can run in parallel.
        :raises CircularDependencyError: If a cycle or self-dependency is detected.
        """
        # Collect all tasks (including those only listed as prerequisites)
        all_tasks = set(dependencies.keys())
        for deps in dependencies.values():
            all_tasks.update(deps)

        if not all_tasks:
            return []

        # in_degree: count of remaining prerequisites for each task
        # dependents: task -> list of tasks that depend on it
        in_degree = {task: 0 for task in all_tasks}
        dependents = {task: [] for task in all_tasks}

        for task, deps in dependencies.items():
            unique_deps = set(deps)
            in_degree[task] = len(unique_deps)
            for dep in unique_deps:
                dependents[dep].append(task)

        # Stage 0: tasks with no prerequisites
        current_stage = [task for task, deg in in_degree.items() if deg == 0]
        stages = []
        resolved_count = 0

        while current_stage:
            current_stage.sort()
            stages.append(current_stage)
            resolved_count += len(current_stage)

            next_stage = []
            for task in current_stage:
                for dependent in dependents[task]:
                    in_degree[dependent] -= 1
                    if in_degree[dependent] == 0:
                        next_stage.append(dependent)

            current_stage = next_stage

        if resolved_count < len(all_tasks):
            raise CircularDependencyError("Circular dependency detected.")

        return stages
